INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('BASE64', 'Base64', (SELECT id FROM categorias_algoritmo WHERE codigo = 'CODIFICACION'), 1, 0, 'Codificación binario a texto. NO es cifrado.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('SHA256', 'SHA-256', (SELECT id FROM categorias_algoritmo WHERE codigo = 'HASH'), 1, 1, 'Función hash de 256 bits de la familia SHA-2.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('MD5', 'MD5', (SELECT id FROM categorias_algoritmo WHERE codigo = 'HASH'), 1, 0, 'Hash de 128 bits roto por colisiones. Solo con fines históricos.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('HMAC_SHA256', 'HMAC-SHA256', (SELECT id FROM categorias_algoritmo WHERE codigo = 'HASH'), 2, 1, 'Código de autenticación de mensaje basado en SHA-256 y una clave.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('BCRYPT', 'bcrypt', (SELECT id FROM categorias_algoritmo WHERE codigo = 'PASSWORD'), 2, 1, 'Hash adaptativo para contraseñas con sal y costo configurable.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('ARGON2ID', 'Argon2id', (SELECT id FROM categorias_algoritmo WHERE codigo = 'PASSWORD'), 2, 1, 'Ganador de la Password Hashing Competition, exigente en memoria.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('PBKDF2', 'PBKDF2-HMAC-SHA256', (SELECT id FROM categorias_algoritmo WHERE codigo = 'PASSWORD'), 2, 1, 'Derivación de claves con muchas iteraciones de HMAC.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('RC4', 'RC4 (ARCFOUR)', (SELECT id FROM categorias_algoritmo WHERE codigo = 'SIMETRICO'), 2, 0, 'Cifrado de flujo obsoleto. Se estudia en la Parte II.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('AES_CBC', 'AES-128-CBC', (SELECT id FROM categorias_algoritmo WHERE codigo = 'SIMETRICO'), 2, 1, 'Cifrado de bloque en modo CBC con relleno PKCS5. Sin autenticación.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('AES_GCM', 'AES-256-GCM', (SELECT id FROM categorias_algoritmo WHERE codigo = 'SIMETRICO'), 2, 1, 'Cifrado autenticado (AEAD) recomendado hoy para datos.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('CHACHA20', 'ChaCha20-Poly1305', (SELECT id FROM categorias_algoritmo WHERE codigo = 'SIMETRICO'), 3, 1, 'Cifrado de flujo autenticado moderno, rápido sin hardware AES.');
INSERT OR IGNORE INTO algoritmos (codigo, nombre, categoria_id, nivel_minimo_ejecucion, es_seguro, descripcion_corta) VALUES ('RSA_OAEP', 'RSA-2048 OAEP', (SELECT id FROM categorias_algoritmo WHERE codigo = 'ASIMETRICO'), 3, 1, 'Cifrado de clave pública con relleno OAEP y SHA-256.');
