INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BASE64'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Convierte bytes en texto usando 64 caracteres imprimibles. Cualquiera puede revertirlo, por eso no protege nada.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BASE64'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Toma 3 bytes (24 bits), los parte en 4 grupos de 6 bits y busca cada grupo en la tabla A-Z a-z 0-9 + /. Si faltan bytes se rellena con =.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BASE64'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'No hay secreto: no ofrece confidencialidad ni integridad. Su error clásico es confundirlo con cifrado al guardar contraseñas o tokens.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BASE64'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa java.util.Base64 con el codificador básico. El laboratorio muestra los bytes UTF-8 y los grupos de 6 bits.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Resume cualquier mensaje en 32 bytes. Un cambio mínimo en la entrada cambia todo el resultado.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Procesa el mensaje en bloques de 512 bits con 64 rondas de rotaciones, desplazamientos y sumas modulares sobre ocho registros de 32 bits.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Resistente a colisiones hoy, pero es RÁPIDO: por sí solo no sirve para contraseñas porque permite probar miles de millones de intentos por segundo.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa MessageDigest con SHA-256. Verificar compara el hash calculado con el recibido en tiempo constante.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'MD5'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Produce 16 bytes. Está roto: se fabrican colisiones en segundos, no debe usarse para seguridad.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'MD5'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Cuatro rondas de 16 operaciones sobre bloques de 512 bits con un estado de 128 bits.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'MD5'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Colisiones prácticas desde 2004. Aún sirve como suma de verificación no adversarial, nunca para firmas ni contraseñas.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'MD5'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa MessageDigest con MD5 solo para mostrar por qué fue reemplazado por SHA-2.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'HMAC_SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Combina un hash con una clave secreta para garantizar que el mensaje no fue alterado y viene de quien conoce la clave.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'HMAC_SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Calcula H((K xor opad) || H((K xor ipad) || mensaje)). La doble capa evita ataques de extensión de longitud.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'HMAC_SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Seguro mientras la clave sea secreta y larga. Comparar el resultado con == filtra información por tiempos, por eso se usa comparación constante.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'HMAC_SHA256'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa javax.crypto.Mac con HmacSHA256 y la clave que escribe el usuario. Verificar usa MessageDigest.isEqual.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BCRYPT'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Algoritmo pensado para guardar contraseñas: lento a propósito y con sal aleatoria incluida en el resultado.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BCRYPT'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Se basa en el cifrado Blowfish con un calendario de claves costoso (EksBlowfish). El costo c significa 2^c iteraciones. El resultado tiene versión, costo, sal de 22 caracteres y hash de 31.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BCRYPT'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Resiste GPU de forma moderada y limita la contraseña a 72 bytes. Subir el costo con los años mantiene el ataque caro. Es el algoritmo que protege el login de este sistema.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'BCRYPT'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa BCryptPasswordEncoder de Spring Security. El login real llama a matches() y nunca descifra el hash.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'ARGON2ID'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Hash de contraseñas moderno que obliga a gastar memoria, lo que encarece los ataques con GPU y ASIC.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'ARGON2ID'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Llena una matriz de bloques de 1 KiB (parámetro m), la recorre t veces con p carriles paralelos y mezcla con la función Blake2b. La variante id combina acceso dependiente e independiente de los datos.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'ARGON2ID'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Recomendado por OWASP como primera opción. Los parámetros m, t y p deben calibrarse al hardware del servidor.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'ARGON2ID'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa Argon2PasswordEncoder de Spring Security con BouncyCastle y los valores por defecto de Spring Security 5.8.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'PBKDF2'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Deriva claves o hashes repitiendo HMAC muchas veces con una sal. Es el estándar más antiguo y compatible.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'PBKDF2'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Aplica HMAC-SHA256 de forma encadenada N iteraciones sobre contraseña y sal, y concatena bloques hasta alcanzar el largo pedido.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'PBKDF2'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Solo es costoso en CPU, no en memoria, así que se acelera bien con GPU. Hoy se requieren cientos de miles de iteraciones.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'PBKDF2'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa SecretKeyFactory con PBKDF2WithHmacSHA256, 120000 iteraciones y sal de 16 bytes. Se guarda como pbkdf2_sha256$iteraciones$sal$hash.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RC4'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Cifrado de flujo muy simple y muy usado en el pasado. Hoy se considera inseguro.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RC4'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Inicializa una permutación de 256 bytes con la clave (KSA) y genera un flujo pseudoaleatorio que se combina con XOR sobre el texto (PRGA).');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RC4'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Sesgos en los primeros bytes del flujo permitieron romper WEP y TLS con RC4. No tiene autenticación ni nonce, y reutilizar la clave revela el XOR de los mensajes.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RC4'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa Cipher con ARCFOUR. La clave se deriva de la frase con PBKDF2 y la salida es Base64 de sal más texto cifrado.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_CBC'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Cifra por bloques de 16 bytes encadenando cada bloque con el anterior mediante un IV aleatorio.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_CBC'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Cada bloque en claro se combina con XOR con el bloque cifrado anterior (el primero usa el IV) y luego se cifra con AES en 10 rondas para clave de 128 bits.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_CBC'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Confidencialidad correcta pero SIN integridad: un atacante puede modificar bloques sin que se note y habilita ataques de padding oracle.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_CBC'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa AES/CBC/PKCS5Padding. La clave de 128 bits sale de PBKDF2 y la salida es Base64 de sal, IV y texto cifrado.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_GCM'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Cifra y autentica a la vez. Si alguien altera un solo bit, el descifrado falla.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_GCM'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Usa el modo contador (CTR) para cifrar y GHASH sobre el texto cifrado para producir una etiqueta de 128 bits. El nonce de 12 bytes nunca debe repetirse con la misma clave.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_GCM'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Opción recomendada para cifrar datos. Reutilizar el nonce con la misma clave destruye la seguridad y existe un límite práctico de datos por clave.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'AES_GCM'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa AES/GCM/NoPadding con clave de 256 bits derivada por PBKDF2 y un nonce aleatorio por mensaje.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'CHACHA20'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Cifrado de flujo moderno con autenticación Poly1305, alternativa a AES-GCM.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'CHACHA20'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Genera bloques de flujo con rondas de suma, rotación y XOR sobre una matriz de 16 palabras de 32 bits y calcula un MAC Poly1305 sobre el texto cifrado.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'CHACHA20'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Rápido en dispositivos sin aceleración AES y resistente a ataques por tiempo en software. Igual que GCM, el nonce no debe repetirse.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'CHACHA20'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'Se usa ChaCha20-Poly1305 de la JCE con clave de 256 bits derivada por PBKDF2 y nonce de 12 bytes.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RSA_OAEP'), (SELECT id FROM tipos_seccion WHERE codigo = 'RESUMEN'), 'Cifra con una clave pública y solo la clave privada puede descifrar. Sirve para intercambiar secretos pequeños.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RSA_OAEP'), (SELECT id FROM tipos_seccion WHERE codigo = 'COMO_FUNCIONA'), 'Se basa en la dificultad de factorizar n = p*q. Se cifra c = m^e mod n y se descifra m = c^d mod n. OAEP añade relleno aleatorio para que el cifrado sea probabilístico.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RSA_OAEP'), (SELECT id FROM tipos_seccion WHERE codigo = 'ANALISIS_SEGURIDAD'), 'Con 2048 bits se considera seguro hoy. Solo cifra mensajes cortos (190 bytes con OAEP y SHA-256), por eso en la práctica se cifra una clave simétrica. Sin OAEP sería vulnerable.');
INSERT OR IGNORE INTO secciones_algoritmo (algoritmo_id, tipo_seccion_id, contenido) VALUES ((SELECT id FROM algoritmos WHERE codigo = 'RSA_OAEP'), (SELECT id FROM tipos_seccion WHERE codigo = 'IMPLEMENTACION'), 'El par de claves se genera una vez y se guarda en la tabla claves_demo. Se usa RSA/ECB/OAEPWithSHA-256AndMGF1Padding.');
